test('large assets use immutable Cloudflare tiers without local binary fallbacks',()=>{const h=read('index.html'),pipeline=read('tools/asset-pipeline.cjs'),site=read('tools/cloudflare-site.cjs'),gitBuild=read('tools/build-git.cjs'),bundle=read('tools/r2-media-bundle.cjs'),restore=read('tools/fetch-source-assets.cjs'),worker=read('cloudflare/worker.js'),revision=JSON.parse(read('assets/revision.json')).version,assets=read('src/assets.js');assert.equal(revision,'assetpack-20260914-r6');assert.match(h,new RegExp(`src/assets\\.js\\?v=${revision}`));assert.match(h,new RegExp(`src/sky-asset\\.js\\?v=${revision}`));assert.ok(Buffer.byteLength(assets)<100000);assert.doesNotMatch(assets,/data:image\/webp;base64/);assert.match(pipeline,/TEXTURE_WIDTHS=Object\.freeze\(\[512,1024,2048,4096\]\)/);assert.match(pipeline,/fallback:remote\(entry\.tiers\[0\]\.path\)/);assert.doesNotMatch(pipeline,/offlineAssetScript|data:image\/webp;base64/);assert.doesNotMatch(site,/fs\.cpSync\(media/);assert.match(site,/\/src\/locales\/\*/);assert.match(site,/Access-Control-Allow-Origin: \*/);assert.match(bundle,/checksum mismatch/);assert.match(gitBuild,/prepareSite\(root\)/);assert.match(restore,/Restored/);assert.match(worker,/SOLAR_TIME_MEDIA\.get\(key,\{range:request\.headers\}\)/);assert.match(worker,/max-age=31536000, immutable/);});
