test('all body-card introductions explain composition without repeating orbital periods',()=>{const astro=read('src/astro.js'),bodies=['en','chn','jpn','hi','es','de','fr'].map(code=>JSON.parse(read('src/locales/'+code+'.json')).bodies);for(const token of ['수소와 헬륨','금속성 핵','이산화탄소 대기','액체 물의 바다','극관과 지하','가스 거대 행성','물얼음 지각','고리는 물얼음','얼음 거대 행성','질소·메테인·일산화탄소 얼음','극지 토양과 분화구'])assert.ok(astro.includes(token),token);for(const bodyCopy of bodies)for(const id of ['sun','mercury','venus','earth','moon','mars','jupiter','europa','saturn','uranus','neptune','pluto'])assert.ok(bodyCopy[id],id);const copy=JSON.stringify(bodies);assert.doesNotMatch(astro,/description:'[^']*(?:공전|한 바퀴|한 해|\d+\.\d+일)/);assert.doesNotMatch(copy,/shortest year|longer year|27\.32 days|3\.55 days|165 years|最短的一年|27\.32 日|3\.55 日|165 年|最も短い一年|27\.32日|3\.55日|165年|27,32|3,55|165 ans|165 Jahren|परिक्रमा/);});
test('standalone artifacts and their publishing path are completely removed',()=>{const ignore=read('.gitignore'),upload=read('tools/upload-r2.cjs'),pkg=read('package.json'),launcher=read('Launch-SolarTime.ps1');assert.equal(fs.existsSync(path.join(root,'tools/build.cjs')),false);assert.equal(fs.existsSync(path.join(root,'tools/standalone-release.cjs')),false);assert.doesNotMatch(pkg,/stage:standalone|"build":\s*"node tools\/build\.cjs"/);assert.doesNotMatch(upload,/standalone|\.html/);assert.doesNotMatch(ignore,/dist\/Solar-Time/);assert.doesNotMatch(launcher,/dist\/|Solar-Time_v/);});
test('fullscreen redraw reveals only complete same-size GPU and canvas frames',()=>{const a=read('src/app.js'),s=read('src/surface.js'),css=read('styles.css');const viewport=a.slice(a.indexOf('let resizeFrame=0'),a.indexOf("window.addEventListener('resize',refreshViewport"));assert.match(viewport,/viewportRevision=0/);assert.match(viewport,/renderer\.resize\(\);renderer\.draw\(clock\.value\(mono,Date\.now\(\)\),effectTime,mono\);renderer\.gpu\?\.flush\?\.\(\);cameraUi\(\)/);assert.match(viewport,/stablePaints<2\|\|revision!==viewportRevision/);assert.ok(viewport.indexOf('prepareViewportFrame(mono)')<viewport.lastIndexOf('revealViewportLayers()'));assert.match(s,/flush\(\)\{if\(!this\.disposed&&!this\.contextLost\)this\.gl\.flush\(\);\}/);assert.match(a,/viewportLayers=\[\$\('planet-layer'\),\$\('universe'\)\]/);assert.match(css,/#planet-layer,#universe\{opacity:1;transition:opacity 1\.4s ease\}/);assert.match(css,/#planet-layer\.viewport-resizing,#universe\.viewport-resizing\{opacity:0;transition:none\}/);assert.match(a,/window\.addEventListener\('resize',refreshViewport/);});
test('one short Escape exits fullscreen without the browser keyboard lock',()=>{const a=read('src/app.js'),escape=a.slice(a.indexOf('function handleEscape()'),a.indexOf('// A single idle owner'));assert.doesNotMatch(a,/navigator\.keyboard\?\.(?:lock|unlock)/);assert.ok(escape.indexOf("if(document.fullscreenElement){exitFullscreen();return;}")<escape.indexOf('if(zen){setZen(false);return;}'));assert.match(a,/if\(document\.fullscreenElement\)\{event\.preventDefault\(\);event\.stopImmediatePropagation\(\);\}\s*if\(!event\.repeat\)handleEscape\(\);return;/);assert.match(a,/escapeLock:'native'/);assert.doesNotMatch(a,/ESC를 길게|Hold ESC|长按 ESC|長押し/);});
