test('one release data file keeps every localized history at the original item count',()=>{const notes=require('../src/release-notes.js');assert.equal(notes.RELEASES[0].version,'0.40');assert.ok(notes.RELEASES.length>10);assert.ok(notes.SOURCE_BYTES>0);assert.ok(notes.RELEASES.every(item=>item.items.length>=3&&item.items.length<=5));for(const code of ['en','chn','jpn','hi','es','de','fr']){assert.equal(notes.LOCALIZED_SUMMARIES[code].length,notes.RELEASES.length,code);for(const release of notes.RELEASES){const items=notes.itemsFor(release,code);assert.equal(items.length,release.items.length,code+' '+release.version);assert.ok(items.every(item=>typeof item==='string'&&item.length>10),code+' '+release.version);}}assert.deepEqual(notes.itemsFor(notes.RELEASES[0],'kor'),notes.RELEASES[0].items);const nav=notes.createReleaseNotesNavigator();assert.equal(nav.current().hasNewer,false);assert.equal(nav.older().release.version,notes.RELEASES[1].version);assert.equal(nav.newer().release.version,'0.40');assert.deepEqual(fs.readdirSync(root).filter(name=>/^UPDATE_v.*\.md$/i.test(name)),[]);});
